def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            chunk = f.read(1024 * 1024)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def find_root(value: str | None) -> Path:
    candidates: list[Path] = []
    if value:
        candidates.append(Path(value))
    candidates.extend([Path.cwd(), Path(r"C:\PhoCap")])
    for item in candidates:
        try:
            item = item.resolve()
        except Exception:
            continue
        if (item / "app" / "main.py").is_file() and (item / "app" / "models.py").is_file():
            return item
    raise SystemExit("Không tìm thấy dự án. Hãy đặt bộ cài trong C:\\PhoCap và chạy tại C:\\PhoCap.")


def db_check(db_path: Path) -> tuple[str, int, list[str]]:
    if not db_path.is_file():
        return "missing", 0, ["Không tìm thấy data/phocap.db"]
    conn = sqlite3.connect(str(db_path))
    try:
        integrity = str(conn.execute("PRAGMA integrity_check").fetchone()[0])
        fk_count = len(list(conn.execute("PRAGMA foreign_key_check")))
        required = {
            "classes": {"id", "school_id", "school_year_id", "code", "name", "is_active"},
            "schools": {"id", "commune_id", "code", "name", "is_active"},
            "school_years": {"id", "code", "name", "is_active"},
            "school_network_year_data": {"school_id", "school_year_id", "level_code"},
            "thpt_school_references": {"id", "official_school_id", "school_code", "school_name"},
            "survey_batches": {"id", "school_year_id", "commune_id", "is_locked"},
            "survey_commune_execution_states": {"survey_batch_id", "is_commune_locked", "is_province_locked"},
            "survey_school_assignments": {"survey_batch_id", "school_id", "is_locked"},
        }
        errors: list[str] = []
        for table, cols in required.items():
            exists = conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,)
            ).fetchone()
            if not exists:
                errors.append(f"Thiếu bảng {table}")
                continue
            actual = {str(row[1]) for row in conn.execute(f'PRAGMA table_info("{table}")')}
            missing = sorted(cols - actual)
            if missing:
                errors.append(f"Bảng {table} thiếu cột: {', '.join(missing)}")
        return integrity, fk_count, errors
    finally:
        conn.close()


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: cần đúng 1 vị trí, tìm thấy {count}.")
    return text.replace(old, new, 1)


def patch_main(text: str) -> str:
    text = replace_once(
        text,
        "from app.routers.students import router as students_router\n",
        "from app.routers.students import router as students_router\n"
        "# === BAI_13B_11_16_1_CLASSROOM_CATALOG_IMPORT ===\n"
        "from app.routers.classrooms import router as classrooms_router\n",
        "main.py import",
    )
    text = replace_once(
        text,
        "app.include_router(students_router)\n",
        "app.include_router(students_router)\n"
        "# === BAI_13B_11_16_1_CLASSROOM_CATALOG_INCLUDE ===\n"
        "app.include_router(classrooms_router)\n",
        "main.py include",
    )
    return text


