def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", default=None)
    args = parser.parse_args()
    root = find_root(args.root)

    main_path = root / "app" / "main.py"
    access_path = root / "app" / "access_control.py"
    menu_path = root / "app" / "templates" / "partials" / "dropdown_menu_v1.html"
    router_path = root / "app" / "routers" / "classrooms.py"
    template_path = root / "app" / "templates" / "classrooms" / "list.html"
    db_path = root / "data" / "phocap.db"

    print("=" * 100)
    print("BÀI 13B-11-16.1 - DANH MỤC LỚP 4 CẤP")
    print("Mầm non - Tiểu học - THCS - THPT")
    print("=" * 100)
    print(f"Dự án: {root}")

    current_main = main_path.read_text(encoding="utf-8")
    current_access = access_path.read_text(encoding="utf-8")
    current_menu = menu_path.read_text(encoding="utf-8")

    if INSTALL_MARKER in current_main and router_path.is_file() and template_path.is_file():
        print("Bộ cài đã có trong dự án. Không cài lặp.")
        return 0

    for rel, expected in EXPECTED_HASHES.items():
        path = root / rel
        actual = sha256(path)
        print(f"{rel}: {actual}")
        if actual != expected:
            print("\nDỪNG AN TOÀN: mã nguồn đã khác bản đã khảo sát.")
            print(f"File khác: {rel}")
            print("Không tự ghi đè. Hãy gửi lại ZIP mã nguồn mới nhất nếu anh đã sửa thêm sau bản hiện tại.")
            return 2

    integrity, fk_count, schema_errors = db_check(db_path)
    print(f"Database integrity_check: {integrity}")
    print(f"Database foreign_key_check: {fk_count} lỗi")
    if integrity.lower() != "ok" or fk_count != 0 or schema_errors:
        print("DỪNG AN TOÀN vì database chưa đạt kiểm tra.")
        for item in schema_errors:
            print(" -", item)
        return 3

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / "exports" / f"backup_truoc_bai_13b_11_16_1_{stamp}"
    backup_dir.mkdir(parents=True, exist_ok=True)

    originals = {
        main_path: current_main,
        access_path: current_access,
        menu_path: current_menu,
    }
    new_file_existed = {router_path: router_path.exists(), template_path: template_path.exists()}
    if router_path.exists():
        originals[router_path] = router_path.read_text(encoding="utf-8")
    if template_path.exists():
        originals[template_path] = template_path.read_text(encoding="utf-8")

    for path in originals:
        rel = path.relative_to(root)
        dest = backup_dir / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, dest)

    backup_db = backup_dir / "data" / "phocap.db"
    backup_db.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(db_path, backup_db)

    try:
        main_path.write_text(patch_main(current_main), encoding="utf-8")
        access_path.write_text(patch_access(current_access), encoding="utf-8")
        menu_path.write_text(patch_menu(current_menu), encoding="utf-8")
        router_path.parent.mkdir(parents=True, exist_ok=True)
        template_path.parent.mkdir(parents=True, exist_ok=True)
        router_path.write_text(ROUTER_CONTENT, encoding="utf-8")
        template_path.write_text(TEMPLATE_CONTENT, encoding="utf-8")

        py_compile.compile(str(main_path), doraise=True)
        py_compile.compile(str(access_path), doraise=True)
        py_compile.compile(str(router_path), doraise=True)

        check = subprocess.run(
            [sys.executable, "-c", "from app.routers.classrooms import router; print(len(router.routes))"],
            cwd=str(root),
            capture_output=True,
            text=True,
            timeout=60,
        )
        if check.returncode != 0:
            raise RuntimeError("Không import được router lớp học: " + (check.stderr or check.stdout))

        from jinja2 import Environment, FileSystemLoader
        env = Environment(loader=FileSystemLoader(str(root / "app" / "templates")))
        env.get_template("classrooms/list.html")
        env.get_template("partials/dropdown_menu_v1.html")

        integrity2, fk_count2, schema_errors2 = db_check(db_path)
        if integrity2.lower() != "ok" or fk_count2 != 0 or schema_errors2:
            raise RuntimeError("Database không đạt kiểm tra sau cài đặt.")

    except Exception as exc:
        print("\nCÀI ĐẶT LỖI - ĐANG TỰ KHÔI PHỤC.")
        for path, content in originals.items():
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
        for path, existed in new_file_existed.items():
            if not existed and path.exists():
                path.unlink()
        print("Đã khôi phục mã nguồn về trước khi cài.")
        print("Lỗi:", exc)
        return 4

    report = root / "exports" / f"bao_cao_cai_dat_bai_13b_11_16_1_{stamp}.txt"
    lines = [
        "BÁO CÁO CÀI ĐẶT BÀI 13B-11-16.1 - DANH MỤC LỚP 4 CẤP",
        f"Thời gian: {datetime.now():%d/%m/%Y %H:%M:%S}",
        f"Dự án: {root}",
        "",
        "ĐÃ CÀI:",
        "- Danh mục lớp Mầm non.",
        "- Danh mục lớp Tiểu học.",
        "- Danh mục lớp THCS.",
        "- Danh mục lớp THPT (các trường THPT đã liên kết School chính thức).",
        "- Quyền: Sở/Xã/Trường quản lý đúng phạm vi; Phòng ban chỉ xem; Giáo viên không quản trị.",
        "- Thêm nhiều lớp cùng lúc, sửa tên/mã lớp, khóa/mở lớp, sao chép lớp năm trước.",
        "- Dùng trực tiếp bảng classes hiện có; không đổi cấu trúc database.",
        "- Khi trường/xã/Sở đã khóa đợt tương ứng, danh mục lớp của năm học đó cũng không cho sửa.",
        "- API lớp hiện có /hoc-sinh/api/lop tự nhìn thấy lớp mới đang hoạt động.",
        "",
        f"Backup: {backup_dir}",
        f"Database integrity_check: {integrity2}",
        f"Database foreign_key_check: {fk_count2} lỗi",
    ]
    report.write_text("\n".join(lines) + "\n", encoding="utf-8-sig")

    print("\n" + "=" * 100)
    print("CÀI ĐẶT THÀNH CÔNG")
    print("=" * 100)
    print("Menu mới: 1. Danh mục -> Danh mục lớp Mầm non / Tiểu học / THCS / THPT")
    print("Tài khoản Trường: 1. Danh mục -> Danh mục lớp của trường")
    print(f"Backup: {backup_dir}")
    print(f"Báo cáo: {report}")
    print("\nSau khi khởi động lại Uvicorn, hãy thử:")
    print("Năm học 2026-2027 -> Tiểu học -> Trường Tiểu học Nghi Hoa -> thêm lớp 1A.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
